local NocturnalMaker = {}
local PRODUCTS = {
    simple_wooden_nocturnal = { name = "Preprost leseni nokturnal", woodCost = 2, brassCost = 1, time = 4, cost = 50, navigation = 18, education = 14, happiness = 1, description = "Preprost leseni nokturnal za nočno navigacijo." },
    brass_disc_nocturnal = { name = "Medeninasti nokturnal", woodCost = 1, brassCost = 3, time = 7, cost = 140, navigation = 32, education = 26, happiness = 2, prestige = 2, description = "Medeninasti nokturnal za trgovce." },
    silver_arm_nocturnal = { name = "Srebrnorokavi nokturnal", woodCost = 1, silverCost = 2, brassCost = 2, time = 10, cost = 340, navigation = 48, education = 38, happiness = 2, prestige = 6, description = "Srebrnorokavi nokturnal za plemiče." },
    gold_engraved_nocturnal = { name = "Zlatogravirani nokturnal", woodCost = 1, goldCost = 2, silverCost = 1, brassCost = 2, time = 14, cost = 800, navigation = 62, education = 52, happiness = 3, prestige = 14, description = "Zlatogravirani nokturnal za visoke plemiče." },
    jewel_set_nocturnal = { name = "Draguljnopolnjeni nokturnal", woodCost = 1, goldCost = 2, silverCost = 1, brassCost = 2, jewelCost = 1, time = 18, cost = 1800, navigation = 78, education = 66, happiness = 5, prestige = 27, description = "Nokturnal z draguljem za visoko plemstvo." },
    royal_grand_nocturnal = { name = "Kraljevski veliki nokturnal", woodCost = 2, goldCost = 3, silverCost = 2, brassCost = 1, jewelCost = 2, pearlCost = 2, time = 25, cost = 4000, navigation = 92, education = 88, happiness = 12, prestige = 58, description = "Veliki kraljevski nokturnal z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    nocturnal_workshop = { name = "Nokturnalna delavnica", cost = { gold = 240, wood = 120, stone = 100, brass = 6 }, upkeep = 5, qualityBonus = 5 },
    stellar_loft = { name = "Zvezdna podstrešje", cost = { gold = 850, wood = 240, stone = 240, silver = 6, brass = 8 }, upkeep = 19, qualityBonus = 18 },
    master_astrolabist_atelier = { name = "Mojstrski astrolabist atelje", cost = { gold = 2400, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 55, qualityBonus = 30 },
    royal_nocturnal_palace = { name = "Kraljevska nokturnalna palača", cost = { gold = 9800, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 195, qualityBonus = 55, prestigeBonus = 50 },
}
NocturnalMaker.woodStock = 14; NocturnalMaker.brassStock = 14; NocturnalMaker.silverStock = 6; NocturnalMaker.goldStock = 6; NocturnalMaker.jewelStock = 4; NocturnalMaker.pearlStock = 4
NocturnalMaker.productStock = {}; NocturnalMaker.buildings = {}; NocturnalMaker.maker = nil; NocturnalMaker.activeMaking = {}; NocturnalMaker.totalProducts = 0; NocturnalMaker.dayTimer = 0
function NocturnalMaker.init() NocturnalMaker.woodStock=14; NocturnalMaker.brassStock=14; NocturnalMaker.silverStock=6; NocturnalMaker.goldStock=6; NocturnalMaker.jewelStock=4; NocturnalMaker.pearlStock=4; NocturnalMaker.productStock={}; NocturnalMaker.buildings={}; NocturnalMaker.maker=nil; NocturnalMaker.activeMaking={}; NocturnalMaker.totalProducts=0; NocturnalMaker.dayTimer=0; print("[NocturnalMaker] Royal Nocturnal Maker System initialized (6 products, 4 buildings)") end
function NocturnalMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; NocturnalMaker.maker={name=n or ("Nokturnarist "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nokturnarist najet: %s (spretnost: %d)",NocturnalMaker.maker.name,s),"success") end; return true end
function NocturnalMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function NocturnalMaker.build(id) local ok,e=NocturnalMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(NocturnalMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function NocturnalMaker.getQualityBonus() local b=0; for _,bd in ipairs(NocturnalMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function NocturnalMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and NocturnalMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.brassCost and NocturnalMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and NocturnalMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and NocturnalMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and NocturnalMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and NocturnalMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #NocturnalMaker.buildings==0 then return false,"Potrebna nokturnalna delavnica" end; if not NocturnalMaker.maker then return false,"Potreben nokturnarist" end; return true end
function NocturnalMaker.make(pt,qty) qty=qty or 1; local ok,e=NocturnalMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then NocturnalMaker.woodStock=NocturnalMaker.woodStock-d.woodCost*qty end; if d.brassCost then NocturnalMaker.brassStock=NocturnalMaker.brassStock-d.brassCost*qty end; if d.silverCost then NocturnalMaker.silverStock=NocturnalMaker.silverStock-d.silverCost*qty end; if d.goldCost then NocturnalMaker.goldStock=NocturnalMaker.goldStock-d.goldCost*qty end; if d.jewelCost then NocturnalMaker.jewelStock=NocturnalMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then NocturnalMaker.pearlStock=NocturnalMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if NocturnalMaker.maker then t=math.max(1,t-math.floor(NocturnalMaker.maker.skill/13)) end; table.insert(NocturnalMaker.activeMaking,{id="nocturnal_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,navigation=d.navigation or 0,education=d.education or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function NocturnalMaker.completeMaking(m) local q=1.0+(NocturnalMaker.getQualityBonus()/100); if NocturnalMaker.maker then q=q+(NocturnalMaker.maker.skill/150) end; q=math.min(2.4,q); NocturnalMaker.productStock[m.productType]=(NocturnalMaker.productStock[m.productType] or 0)+m.quantity; NocturnalMaker.totalProducts=NocturnalMaker.totalProducts+m.quantity; if m.navigation>0 and _G.state then _G.state.navigation=(_G.state.navigation or 0)+m.navigation end; if m.education>0 and _G.state then _G.state.education=(_G.state.education or 0)+m.education end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if NocturnalMaker.maker then NocturnalMaker.maker.itemsMade=NocturnalMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then NocturnalMaker.maker.skill=math.min(100,NocturnalMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Nokturnal izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"nocturnal.completed",{productName=m.productName,navigation=m.navigation,education=m.education,prestige=m.prestige,happiness=m.happiness}) end end
function NocturnalMaker.update(dt) if not _G.state then return end; NocturnalMaker.dayTimer=NocturnalMaker.dayTimer+dt; if NocturnalMaker.dayTimer>=30 then NocturnalMaker.dayTimer=0; for i=#NocturnalMaker.activeMaking,1,-1 do local m=NocturnalMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then NocturnalMaker.completeMaking(m); table.remove(NocturnalMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(NocturnalMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if NocturnalMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function NocturnalMaker.getStats() return {woodStock=NocturnalMaker.woodStock,brassStock=NocturnalMaker.brassStock,silverStock=NocturnalMaker.silverStock,goldStock=NocturnalMaker.goldStock,jewelStock=NocturnalMaker.jewelStock,pearlStock=NocturnalMaker.pearlStock,productStock=NocturnalMaker.productStock,numBuildings=#NocturnalMaker.buildings,hasMaker=NocturnalMaker.maker~=nil,makerName=NocturnalMaker.maker and NocturnalMaker.maker.name or "—",makerSkill=NocturnalMaker.maker and NocturnalMaker.maker.skill or 0,activeMaking=#NocturnalMaker.activeMaking,totalProducts=NocturnalMaker.totalProducts} end
return NocturnalMaker
